// ─── modelos/formato.js ──────────────────────────────────────────────────────────────────────
// Fechas y textos que comparten todos los flujos. Las fechas viajan como texto ISO
// (AAAA-MM-DD o fecha y hora con zona) para que las funciones sean fáciles de probar.

/** 2026-10-07 → «07/10/2026». */
const fecha = (iso) => DateTime.fromISO(iso).toFormat('dd/MM/yyyy');

/** 2026-10-07 → «7 de oct». */
const fechaCorta = (iso) => DateTime.fromISO(iso).setLocale('es').toFormat("d 'de' LLL");

/** Fecha y hora conservando la zona horaria con la que se guardó: «13/10/2026 a las 10:56». */
const fechaHora = (iso) => DateTime.fromISO(iso, { setZone: true }).setLocale('es').toFormat("dd/MM/yyyy 'a las' HH:mm");

/** Días enteros entre dos fechas ISO (negativo si `hasta` es anterior). */
const diasEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'days').days);

/** Suma (o resta) días a una fecha ISO. */
const sumarDias = (iso, dias) => DateTime.fromISO(iso).plus({ days: dias }).toISODate();

/** Minutos enteros entre dos instantes ISO. */
const minutosEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'minutes').minutes);

/** «2026-05» → «Mayo 2026». */
const mes = (aaaaMm) => mayuscula(DateTime.fromISO(`${aaaaMm}-01`).setLocale('es').toFormat('LLLL yyyy'));

/** «Del 7 al 13 de octubre de 2026» o «Del 30 de septiembre al 6 de octubre de 2026». */
function rangoFechas(inicioIso, finIso) {
  const a = DateTime.fromISO(inicioIso).setLocale('es');
  const b = DateTime.fromISO(finIso).setLocale('es');
  const inicio = a.month === b.month && a.year === b.year ? a.toFormat('d')
    : a.year === b.year ? a.toFormat("d 'de' LLLL")
      : a.toFormat("d 'de' LLLL 'de' yyyy");
  return `Del ${inicio} al ${b.toFormat("d 'de' LLLL 'de' yyyy")}`;
}

/** 0 → «hoy», 1 → «mañana», 3 → «en 3 días». */
const cuando = (dias) => (dias === 0 ? 'hoy' : dias === 1 ? 'mañana' : `en ${dias} días`);

/** 1 → «ayer», 6 → «hace 6 días». */
const hace = (dias) => (dias === 1 ? 'ayer' : `hace ${dias} días`);

/** 1 → «1 préstamo», 3 → «3 préstamos». */
const plural = (n, uno, varios) => `${n} ${n === 1 ? uno : varios}`;

/** Primera letra en mayúscula. */
const mayuscula = (s) => s[0].toUpperCase() + s.slice(1);

/** 75 → «1 h 15 min», 1 → «1 minuto». */
const duracion = (minutos) => (minutos < 60
  ? plural(minutos, 'minuto', 'minutos')
  : `${Math.floor(minutos / 60)} h ${minutos % 60} min`);

// ─── modelos/informe.js ──────────────────────────────────────────────────────────────────────
// Datos del informe semanal a partir de las respuestas de la API (sin nada de presentación).

/**
 * @param o.stats      respuesta de GET /stats
 * @param o.libros     respuesta de GET /books
 * @param o.vencidos   préstamos con status=OVERDUE
 * @param o.enPlazo    préstamos con status=ACTIVE ordenados por vencimiento
 * @param o.recientes  préstamos del más reciente al más antiguo
 * @param o.hoy        AAAA-MM-DD
 */
function datosInforme({ stats, libros, vencidos, enPlazo, recientes, hoy }) {
  const inicioSemana = sumarDias(hoy, -6); // los últimos 7 días, hoy incluido
  const enUnaSemana = sumarDias(hoy, 7);
  const nuevos = recientes.filter((p) => p.loanDate >= inicioSemana && p.loanDate <= hoy);
  return {
    hoy,
    inicioSemana,
    vencidos,
    nuevos,
    proximos: enPlazo.filter((p) => p.dueDate <= enUnaSemana),
    agotados: libros.filter((l) => l.availableCopies === 0),
    masPrestados: stats.topBooks.slice(0, 5),
    porMes: stats.loansByMonth,
    indicadores: [
      { nombre: 'Libros', valor: stats.totalBooks },
      { nombre: 'Usuarios', valor: stats.totalMembers },
      { nombre: 'En plazo', valor: stats.activeLoans },
      { nombre: 'Vencidos', valor: stats.overdueLoans, alerta: true },
      { nombre: 'Nuevos (7 días)', valor: nuevos.length },
    ],
  };
}

// ─── vistas/html.js ──────────────────────────────────────────────────────────────────────────
// Utilidades HTML comunes a todas las vistas.

/** Escapa un texto para insertarlo en HTML (nombres y títulos vienen de la base de datos). */
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// ─── vistas/plantilla-correo.js ──────────────────────────────────────────────────────────────
// Plantilla común de los correos: cabecera con degradado, tarjeta blanca, pie y piezas reutilizables.
// Usa los colores de la web de la biblioteca. Todo va con estilos en línea y tablas: es lo único
// que respetan por igual Gmail, Outlook y los clientes de móvil.

const COLOR = {
  marca: '#4f46e5', marca2: '#7c3aed', marcaSuave: '#eef2ff',
  texto: '#0f172a', suave: '#64748b', borde: '#e2e8f0', fondo: '#f1f5f9', tarjeta: '#ffffff', sutil: '#f8fafc',
  peligro: '#dc2626', peligroSuave: '#fef2f2', peligroBorde: '#fecaca',
  aviso: '#b45309', avisoSuave: '#fffbeb', avisoBorde: '#fde68a',
  exito: '#047857', exitoSuave: '#ecfdf5', exitoBorde: '#a7f3d0',
};
/** Color vivo de las líneas laterales de tarjetas y recuadros. */
const ACENTO = { peligro: '#ef4444', aviso: '#f59e0b', exito: '#10b981', marca: COLOR.marca, neutro: '#94a3b8' };
/** [texto, fondo, borde] de cada tono. */
const TONOS = {
  peligro: [COLOR.peligro, COLOR.peligroSuave, COLOR.peligroBorde],
  aviso: [COLOR.aviso, COLOR.avisoSuave, COLOR.avisoBorde],
  exito: [COLOR.exito, COLOR.exitoSuave, COLOR.exitoBorde],
  marca: [COLOR.marca, COLOR.marcaSuave, '#c7d2fe'],
  neutro: [COLOR.suave, COLOR.sutil, COLOR.borde],
};
const FUENTE = "-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

/** Etiqueta redondeada de estado («Vencido hace 6 días»). */
const pastilla = (texto, tono = 'neutro') => {
  const [color, fondo, borde] = TONOS[tono];
  return `<span style="display:inline-block;padding:3px 10px;border-radius:999px;background:${fondo};border:1px solid ${borde};color:${color};font-size:12px;font-weight:600;line-height:18px;white-space:nowrap">${esc(texto)}</span>`;
};

/** Recuadro de color para mensajes importantes. */
const recuadro = (html, tono = 'marca', margen = '20px 0 0') => {
  const [, fondo, borde] = TONOS[tono];
  return `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin:${margen}"><tr>
<td style="background:${fondo};border:1px solid ${borde};border-left:4px solid ${ACENTO[tono]};border-radius:8px;padding:12px 16px;font-size:14px;line-height:21px;color:${COLOR.texto}">${html}</td></tr></table>`;
};

/** Título de sección dentro del cuerpo, con contador opcional. */
const seccion = (titulo, cantidad) => `<h2 style="margin:28px 0 10px;font-size:15px;line-height:22px;font-weight:700;color:${COLOR.texto}">${esc(titulo)}${
  cantidad === undefined ? '' : ` <span style="display:inline-block;margin-left:4px;padding:0 8px;border-radius:999px;background:${COLOR.marcaSuave};color:${COLOR.marca};font-size:12px;line-height:20px;vertical-align:1px">${cantidad}</span>`}</h2>`;

/**
 * Documento completo del correo.
 * @param o.etiqueta    texto pequeño sobre el título («RECORDATORIO DE PRÉSTAMOS»)
 * @param o.vistaPrevia texto que muestran los clientes de correo junto al asunto
 * @param o.cuerpo      HTML del contenido
 * @param o.pie         HTML del pie (ya escapado)
 * @param o.cabecera    color de la cabecera: 'marca' (índigo), 'peligro' (rojo) o 'exito' (verde)
 */
function correoHtml({ biblioteca, etiqueta, titulo, subtitulo = '', vistaPrevia = '', cuerpo, pie, cabecera = 'marca' }) {
  const [desde, hasta, claro] = {
    marca: [COLOR.marca, COLOR.marca2, '#c7d2fe'],
    peligro: ['#dc2626', '#9f1239', '#fecaca'],
    exito: ['#059669', '#0f766e', '#a7f3d0'],
  }[cabecera];
  return `<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>${esc(titulo)}</title></head>
<body style="margin:0;padding:0;background:${COLOR.fondo};-webkit-text-size-adjust:100%">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:${COLOR.fondo}">${esc(vistaPrevia)}&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;</div>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:${COLOR.fondo}"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:600px;font-family:${FUENTE}">
<tr><td style="background:${desde};background-image:linear-gradient(135deg,${desde},${hasta});border-radius:14px 14px 0 0;padding:24px 28px">
  <table role="presentation" cellspacing="0" cellpadding="0"><tr>
    <td style="width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,0.18);text-align:center;font-size:19px;line-height:36px">&#128214;</td>
    <td style="padding-left:12px;font-size:15px;font-weight:700;color:#ffffff;letter-spacing:0.2px">${esc(biblioteca)}</td>
  </tr></table>
  <div style="margin-top:20px;font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:${claro}">${esc(etiqueta)}</div>
  <div style="margin-top:4px;font-size:24px;line-height:31px;font-weight:700;color:#ffffff">${esc(titulo)}</div>
  ${subtitulo ? `<div style="margin-top:6px;font-size:14px;line-height:20px;color:#ffffff;opacity:0.9">${esc(subtitulo)}</div>` : ''}
</td></tr>
<tr><td style="background:${COLOR.tarjeta};border:1px solid ${COLOR.borde};border-top:0;border-radius:0 0 14px 14px;padding:28px;font-size:15px;line-height:23px;color:${COLOR.texto}">
${cuerpo}
</td></tr>
<tr><td style="padding:18px 28px 0;text-align:center;font-size:12px;line-height:18px;color:${COLOR.suave}">${pie}</td></tr>
</table>
</td></tr></table>
</body></html>`;
}

// ─── vistas/correo-informe.js ────────────────────────────────────────────────────────────────
// Vista del informe semanal que recibe el bibliotecario.

const th = (t, alinear = 'left') => `<th style="text-align:${alinear};padding:8px 10px;background:${COLOR.sutil};border-bottom:1px solid ${COLOR.borde};font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:0.4px;color:${COLOR.suave}">${t}</th>`;
const td = (t, alinear = 'left', extra = '') => `<td style="text-align:${alinear};padding:10px;border-bottom:1px solid ${COLOR.borde};font-size:14px;line-height:20px;color:${COLOR.texto};${extra}">${t}</td>`;
const tabla = (cabecera, filas) => `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;border:1px solid ${COLOR.borde};border-radius:10px">
<tr>${cabecera.join('')}</tr>${filas.map((f) => `<tr>${f.join('')}</tr>`).join('')}</table>`;
const vacio = (texto, tono = 'exito') => recuadro(tono === 'exito' ? `&#10003; ${esc(texto)}` : esc(texto), tono, '0');
const libro = (titulo) => `<strong style="font-weight:600">${esc(titulo)}</strong>`;

/** Barra horizontal proporcional (para «más prestados» y «por mes»). */
const barra = (valor, maximo) => {
  const ancho = Math.max(4, Math.round((valor / Math.max(1, maximo)) * 100));
  return `<table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr>
<td width="${ancho}%" style="height:10px;border-radius:999px;background:${COLOR.marca};background-image:linear-gradient(90deg,${COLOR.marca},${COLOR.marca2});font-size:0;line-height:0">&nbsp;</td>
<td style="font-size:0;line-height:0">&nbsp;</td></tr></table>`;
};

/** Indicadores: bloques que se recolocan solos en pantallas estrechas. */
const tarjetasIndicadores = (indicadores) => `<div style="text-align:center;font-size:0;margin:0 -4px">${indicadores.map(({ nombre, valor, alerta }) => {
  const tono = !alerta ? 'marca' : valor > 0 ? 'peligro' : 'exito';
  const color = tono === 'marca' ? COLOR.texto : TONOS[tono][0];
  const fondo = tono === 'marca' ? COLOR.sutil : TONOS[tono][1];
  const borde = tono === 'marca' ? COLOR.borde : TONOS[tono][2];
  // 5 × (86 + 8 de relleno + 2 de borde + 8 de margen) = 520 px: caben en una fila del correo (548 px útiles)
  return `<div style="display:inline-block;vertical-align:top;width:86px;margin:4px;padding:12px 4px;border:1px solid ${borde};border-radius:10px;background:${fondo};text-align:center">
<div style="font-size:24px;line-height:30px;font-weight:700;color:${color}">${valor}</div>
<div style="font-size:12px;line-height:16px;color:${COLOR.suave}">${nombre}</div></div>`;
}).join('')}</div>`;

/**
 * @param o.datos      resultado de `datosInforme` (modelos/informe.js)
 * @param o.usuarios   respuesta de GET /members (para enlazar el correo de cada usuario)
 * @param o.biblioteca nombre de la biblioteca
 * @returns {{ asunto, html, texto }}
 */
function correoInforme({ datos, usuarios, biblioteca }) {
  const { hoy, inicioSemana, vencidos, proximos, nuevos, agotados, masPrestados, porMes, indicadores } = datos;
  const correos = new Map(usuarios.map((u) => [u.id, u.email]));
  const contacto = (memberId, nombre) => (correos.get(memberId)
    ? `<a href="mailto:${esc(correos.get(memberId))}" style="color:${COLOR.marca};text-decoration:none">${esc(nombre)}</a>`
    : esc(nombre));
  const rango = rangoFechas(inicioSemana, hoy);
  const maxLibro = Math.max(1, ...masPrestados.map((e) => e.count));
  const maxMes = Math.max(1, ...porMes.map((m) => m.count));

  const cuerpo = [
    tarjetasIndicadores(indicadores),

    seccion('Préstamos vencidos', vencidos.length),
    vencidos.length
      ? tabla([th('Libro'), th('Usuario'), th('Retraso', 'right')],
        vencidos.map((p) => [
          td(`${libro(p.bookTitle)}<div style="font-size:12px;color:${COLOR.suave}">Venció el ${fecha(p.dueDate)}</div>`),
          td(contacto(p.memberId, p.memberName)),
          td(pastilla(`${diasEntre(p.dueDate, hoy)} días`, 'peligro'), 'right'),
        ]))
      : vacio('No hay préstamos vencidos.'),

    seccion('Vencen en los próximos 7 días', proximos.length),
    proximos.length
      ? tabla([th('Libro'), th('Usuario'), th('Vence', 'right')],
        proximos.map((p) => {
          const dias = diasEntre(hoy, p.dueDate);
          return [td(libro(p.bookTitle)), td(contacto(p.memberId, p.memberName)),
            td(pastilla(dias === 0 ? 'hoy' : dias === 1 ? 'mañana' : fechaCorta(p.dueDate), 'aviso'), 'right')];
        }))
      : vacio('Ningún préstamo vence esta semana.'),

    seccion('Préstamos de esta semana', nuevos.length),
    nuevos.length
      ? tabla([th('Libro'), th('Usuario'), th('Fecha', 'right')],
        nuevos.map((p) => [td(libro(p.bookTitle)), td(esc(p.memberName)), td(fechaCorta(p.loanDate), 'right', `color:${COLOR.suave};white-space:nowrap`)]))
      : vacio('No se registraron préstamos esta semana.', 'neutro'),

    seccion('Libros agotados', agotados.length),
    agotados.length
      ? tabla([th('Libro'), th('Ejemplares', 'right')],
        agotados.map((l) => [td(`${libro(l.title)}<div style="font-size:12px;color:${COLOR.suave}">${esc(l.author)}</div>`),
          td(pastilla(`0 de ${l.totalCopies}`, 'aviso'), 'right')]))
      : vacio('Todos los libros tienen ejemplares disponibles.'),

    seccion('Los más prestados'),
    masPrestados.length
      ? tabla([th('Libro'), th(''), th('Préstamos', 'right')],
        masPrestados.map((e, i) => [
          td(`<span style="color:${COLOR.suave};padding-right:6px">${i + 1}.</span>${libro(e.label)}`),
          td(barra(e.count, maxLibro), 'left', 'width:30%'),
          td(String(e.count), 'right', 'font-weight:600'),
        ]))
      : vacio('Todavía no hay préstamos.', 'neutro'),

    seccion('Préstamos por mes'),
    tabla([th('Mes'), th(''), th('Préstamos', 'right')],
      porMes.map((m) => [td(mes(m.label), 'left', 'white-space:nowrap'), td(barra(m.count, maxMes), 'left', 'width:50%'),
        td(String(m.count), 'right', 'font-weight:600')])),
  ].join('\n');

  const resumen = [
    vencidos.length ? plural(vencidos.length, 'préstamo vencido', 'préstamos vencidos') : 'Sin préstamos vencidos',
    plural(nuevos.length, 'préstamo nuevo', 'préstamos nuevos'),
  ].join(' · ');

  const html = correoHtml({
    biblioteca,
    etiqueta: 'Informe semanal',
    titulo: rango,
    subtitulo: resumen,
    vistaPrevia: `${resumen}. ${proximos.length} vencen en los próximos 7 días.`,
    cuerpo,
    pie: `Generado automáticamente por n8n con los datos de ${esc(biblioteca)}.`,
  });

  // --- Versión en texto plano ---
  const lista = (items, linea) => (items.length ? items.map(linea) : ['  Ninguno.']);
  const texto = [
    `Informe semanal · ${biblioteca}`,
    rango,
    '',
    ...indicadores.map(({ nombre, valor }) => `${nombre}: ${valor}`),
    '',
    `PRÉSTAMOS VENCIDOS (${vencidos.length})`,
    ...lista(vencidos, (p) => `  - «${p.bookTitle}», ${p.memberName}: venció el ${fecha(p.dueDate)} (${diasEntre(p.dueDate, hoy)} días)`),
    '',
    `VENCEN EN LOS PRÓXIMOS 7 DÍAS (${proximos.length})`,
    ...lista(proximos, (p) => `  - «${p.bookTitle}», ${p.memberName}: vence el ${fecha(p.dueDate)}`),
    '',
    `PRÉSTAMOS DE ESTA SEMANA (${nuevos.length})`,
    ...lista(nuevos, (p) => `  - «${p.bookTitle}», ${p.memberName} (${fecha(p.loanDate)})`),
    '',
    `LIBROS AGOTADOS (${agotados.length})`,
    ...lista(agotados, (l) => `  - «${l.title}», ${l.author}`),
  ].join('\n');

  return { asunto: `Informe semanal de ${biblioteca}: ${resumen.toLowerCase()}`, html, texto };
}

// ─── controladores/informe-componer.js ───────────────────────────────────────────────────────
// Nodo «Componer informe» (Informe semanal): reúne las respuestas de la API y compone el correo.

function componerInforme({ $, hoy }) {
  const cfg = $('Configuración').first().json;
  const paginas = (nodo) => $(nodo).all().flatMap((i) => i.json.content ?? []);
  const datos = datosInforme({
    stats: $('Estadísticas').first().json,
    libros: $('Libros').all().map((i) => i.json),
    vencidos: paginas('Préstamos vencidos'),
    enPlazo: paginas('Préstamos en plazo'),
    recientes: paginas('Préstamos recientes'),
    hoy,
  });
  const correo = correoInforme({ datos, usuarios: $('Usuarios').all().map((i) => i.json), biblioteca: cfg.nombreBiblioteca });
  return [{ json: { para: cfg.correoBibliotecario, ...correo } }];
}

return await componerInforme({ $, $input, hoy: $today.toISODate(), ahora: $now.toISO(), memoria: $getWorkflowStaticData('global'), helpers: this.helpers });
